SELECT jsonb_build_object('events',(SELECT jsonb_agg(to_jsonb(e)||jsonb_build_object('row_hash',md5(to_jsonb(e)::text)) ORDER BY id_evento) FROM tb_evento_corridas e WHERE id_evento IN (48557,45366,37570,37528)),'routes',(SELECT jsonb_agg(to_jsonb(p)||jsonb_build_object('row_hash',md5(to_jsonb(p)::text)) ORDER BY id_evento_percurso) FROM tb_evento_corridas_percursos p WHERE id_evento IN (48557,45366,37570,37528)),'memberships',(SELECT coalesce(jsonb_agg(to_jsonb(g)),'[]') FROM tb_agregadores_eventos g WHERE id_evento IN (48557,45366,37570,37528)))::text payload
